    TwistSquash::SquashKeyA(MIMOSA_KEY_B_D_IceLaneA, MIMOSA_KEY_B_D_IceLaneB, MIMOSA_KEY_B_D_IceLaneC, MIMOSA_KEY_B_D_IceLaneD, &(pWorkSpace->mKeyBoxB[3U][0]));

    // Key flow — B / E

